// Generated static assets (social card + icons), served by the Worker.
const decode = (b64: string): Uint8Array<ArrayBuffer> => Uint8Array.from(atob(b64), (ch) => ch.charCodeAt(0));

export const OG_IMAGE_PNG = decode("");
export const ICON_512 = decode("");
export const ICON_192 = decode("");
export const ICON_180 = decode("");
export const ICON_48 = decode("");
